    {
      "name": "glossary_term",
      "comment": "术语表",
      "columns": [
        {
          "name": "term_id",
          "comment": "术语ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "source_language_code",
          "comment": "源语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_term",
          "comment": "源术语",
          "constraint": ""
        },
        {
          "name": "translated_term",
          "comment": "标准译法",
          "constraint": ""
        },
        {
          "name": "rule_type",
          "comment": "规则类型（do_not_translate/mandatory/recommended）",
          "constraint": ""
        },
        {
          "name": "context",
          "comment": "使用场景说明",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/deprecated）",
          "constraint": ""
        }
      ],
      "note": "术语管理：禁译词保留原文，强制术语必须使用指定译法，推荐术语建议使用"
    },
    {
      "name": "translatable_field_config",
      "comment": "可翻译字段配置",
      "columns": [
        {
          "name": "config_id",
          "comment": "配置ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "resource_type",
          "comment": "资源类型（开放字段，由业务模块注册）",
          "constraint": ""
        },
        {
          "name": "resource_label",
          "comment": "资源类型显示名称（业务模块注册时提供）",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段标识",
          "constraint": ""
        },
        {
          "name": "field_label",
          "comment": "字段显示名称",
          "constraint": ""
        },
        {
          "name": "key_type",
          "comment": "Key类型（business_mapping/self_managed）",
          "constraint": ""
        },
        {
          "name": "source_system",
          "comment": "来源系统",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（active/inactive/deprecated）",
          "constraint": ""
        }
      ],
      "note": "注册表模式：业务模块注册可翻译字段。key_type 区分业务映射/自管理。resource_type + field_name 联合唯一"
    }
  ],
  "relations": [
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#7B1FA2",
      "penwidth": 1.2
    },
    {
      "from": "translation_job",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#E8833A",
      "penwidth": 1.2
    },
    {
      "from": "translation_job",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#E8833A",
      "penwidth": 1.2
    },
    {
      "from": "translation_job_item",
      "to": "translation_job",
      "type": "N:1",
      "label": "归属任务",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "translation_job_item",
      "to": "translation",
      "type": "N:1",
      "label": "关联翻译",
      "color": "#7B1FA2",
      "penwidth": 1.2
    },
    {
      "from": "glossary_term",
      "to": "language",
      "type": "N:1",
      "label": "源语言",
      "color": "#2E7D32"
    },
    {
      "from": "glossary_term",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#2E7D32"
    },
    {
      "from": "translatable_field_config",
      "to": "translation_job",
      "type": "",
      "label": "字段规则驱动",
      "color": "#2E7D32",
      "style": "dashed",
      "penwidth": 1.0
    },
    {
      "from": "glossary_term",
      "to": "translation_job_item",
      "type": "",
      "label": "术语约束",
      "color": "#2E7D32",
      "style": "dashed",
      "penwidth": 1.0
    }
  ],
  "design_rules": {
    "eav_pattern": "translation 表采用 EAV 模式（resource_type + resource_id + field_name），一张表存储所有业务实体的翻译内容。resource_type 为开放字段（VARCHAR），翻译模块不限定取值范围，由业务模块自行定义",
    "translation_current_record": "translation 表每条记录代表该资源字段+语言方向的当前有效版本（current effective record）。翻译审核通过后原地更新，不在主表追加历史行",
    "translation_no_history_in_main_table": "translation 主表不保留历史版本（does not retain historical versions）；历史变更通过 source_hash + source_version 追踪源内容变化，可选接入版本历史表",
    "translation_unique_key": "translation 唯一性约束由五列联合保证：resource_type + resource_id + field_name + source_language_code + language_code。相同资源字段同一翻译方向只有一条当前记录",
    "translation_strategy": "混合策略：核心内容（商品/类目）集中翻译+人工审核，长尾内容（UGC）AI翻译+抽检。source_hash 检测源内容变化，status=outdated 触发重译",
    "language_fk": "翻译关联 language_code（ISO 639-1），不建 locale 实体。BCP 47 locale 在运行时由 language_code + country_code 拼接",
    "glossary_enforcement": "术语表规则类型：do_not_translate（禁译词，保留原文）、mandatory（强制术语，必须使用指定译法）、recommended（推荐术语，建议使用）",
    "job_lifecycle": "翻译任务生命周期：pending → in_progress → completed/cancelled。任务条目完成后自动回写 translation 表的 translated_value 和 status",
    "translatable_field_config_registry": "translatable_field_config 采用注册表模式：各业务模块主动注册需要翻译的字段（非全量同步）。业务模块在开发阶段声明哪些 resource_type + field_name 需要翻译，只有显式注册的字段才会进入翻译流程。翻译模块不主动扫描或同步业务模块的全部字段，避免数据冗余",
    "resource_type_open_field": "resource_type 在翻译模块所有表中均为开放 VARCHAR 字段，不使用枚举约束。翻译模块不校验其取值，业务模块写什么就是什么（如 spu/sku/product/listing/category/cms/promotion 等）。翻译设置页面按已注册的 resource_type 动态分组展示",
    "audit_fields": "所有实体统一通过数据库层自动维护审计字段（created_by/created_at/updated_by/updated_at），不在 ER 图中逐表重复列出"
  }
}
